const grid=document.getElementById("weekGrid");
const modal=document.getElementById("weekModal");
const tabs=[...document.querySelectorAll(".tab")];
weeks.forEach(w=>{
 const card=document.createElement("article");card.className="week-card";
 card.innerHTML=`<div class="week-card-top"><span class="week-num">WEEK ${String(w.n).padStart(2,"0")}</span><span class="week-arrow">↗</span></div><h3>${w.title}</h3><p>${w.subtitle}</p><span class="open-label">OPEN WEEK CONTENT →</span>`;
 card.addEventListener("click",()=>openWeek(w));grid.appendChild(card);
});
function openWeek(w){
 document.getElementById("modalWeek").textContent=`WEEK ${String(w.n).padStart(2,"0")}`;
 document.getElementById("modalTitle").textContent=w.title;
 document.getElementById("modalSubtitle").textContent=w.subtitle;
 document.getElementById("panelAim").innerHTML=`<div class="aim-box"><h3>Aim</h3><p>${w.aim}</p></div>`;
 document.getElementById("panelContent").innerHTML=w.items.map((item,i)=>`<article class="topic"><h3>${i+1}. ${item.heading}</h3><p>${item.body}</p></article>`).join("");
 const resources=weekResources[w.n]||[];
 const legacy=w.code?[{label:"Additional code / commands",language:"Text",content:w.code}]:[];
 const allBlocks=[...resources,...legacy];
 document.getElementById("panelCode").innerHTML=allBlocks.length?`<div class="code-intro"><h3>Complete weekly code & commands</h3><p>All files for this week are included below. Use the copy button on any block to copy its contents.</p></div>`+allBlocks.map((b,i)=>`<section class="embedded-code"><div class="embedded-code-head"><div><strong>${b.label}</strong><span>${b.language}</span></div><button type="button" class="copy-code" data-code-index="${i}">Copy code</button></div><pre class="embedded-code-content"></pre></section>`).join(""):`<p class="empty-code">No code files are assigned to this week.</p>`;
 document.querySelectorAll("#panelCode .embedded-code-content").forEach((el,i)=>{el.textContent=allBlocks[i].content;});
 document.querySelectorAll("#panelCode .copy-code").forEach((btn,i)=>btn.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(allBlocks[i].content);btn.textContent="Copied!";setTimeout(()=>btn.textContent="Copy code",1400);}catch(e){btn.textContent="Select text to copy";}}));
 document.getElementById("panelResult").innerHTML=`<div class="result-box"><h3>Result</h3><p>${w.result}</p></div>`;
 tabs.forEach(t=>t.classList.toggle("active",t.dataset.tab==="aim"));
 document.querySelectorAll(".panel").forEach(p=>p.classList.remove("active"));
 document.getElementById("panelAim").classList.add("active");
 modal.classList.add("open");modal.setAttribute("aria-hidden","false");document.body.style.overflow="hidden";
 document.getElementById("closeBtn").focus();
}
function closeWeek(){modal.classList.remove("open");modal.setAttribute("aria-hidden","true");document.body.style.overflow="";}
document.getElementById("closeBtn").addEventListener("click",closeWeek);
document.getElementById("backdrop").addEventListener("click",closeWeek);
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&modal.classList.contains("open"))closeWeek();});
tabs.forEach(t=>t.addEventListener("click",()=>{
 tabs.forEach(x=>x.classList.toggle("active",x===t));
 document.querySelectorAll(".panel").forEach(p=>p.classList.remove("active"));
 document.getElementById("panel"+t.dataset.tab[0].toUpperCase()+t.dataset.tab.slice(1)).classList.add("active");
}));
document.getElementById("menuBtn").addEventListener("click",()=>document.querySelector(".topbar nav").classList.toggle("show"));
